    for item in lst:
        result.append(element)
        result.append(item)
    return result

def re_arrange_array(arr):
    i, j = 0, len(arr) - 1
    while i < j:
        if arr[i] < 0:
            i += 1
        elif arr[j] >= 0:
            j -= 1
        else:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
            j -= 1
    return arr

def second_smallest(lst):
    unique_vals = set(lst)
    if len(unique_vals) < 2:
        raise ValueError("List must contain at least two distinct values")
    sorted_vals = sorted(unique_vals)
    return sorted_vals[1]

import re

def remove_multiple_spaces(s: str) -> str:
    # Replace one or more whitespace characters with a single space
    result = re.sub(r'\s+', ' ', s)
    # Strip leading and trailing spaces
    return result.strip()

def is_decimal(s: str) -> bool:
    if not isinstance(s, str):
        return False
    s = s.strip()
    if not s:
        return False

    # Optional sign
    if s[0] in '+-':
        s = s[1:]
    if not s:
        return False

    # Split by decimal point
    parts = s.split('.')
    if len(parts) != 2:
        return False

    integer_part, fractional_part = parts

    # Both parts must be composed only of digits (integer_part can be empty? No, must have digits)
    if not integer_part.isdigit():
        return False
    if len(fractional_part) != 2:
        return False
    if not fractional_part.isdigit():
        return False

    return True

def is_Two_Alter(s: str) -> bool:
    if len(s) == 1:
        return True

    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False

    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0
    max_current = max_global = arr[0]
    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current
    return max_global

import re

def len_log(s):
    words = re.findall(r'\b[a-zA-Z]+\b', s)
    if not words:
        return 0
    return max(len(word) for word in words)

def count_nums(arr):
    def signed_digits(n):
        s = str(n)
        digits = []
        if s[0] == '-':
            # first digit is negative
            digits.append(-int(s[1]))
            digits.extend(int(d) for d in s[2:])
        else:
            digits.extend(int(d) for d in s)
        return digits

    count = 0
    for num in arr:
        digits = signed_digits(num)
        if sum(digits) > 0:
            count += 1
    return count

def strlen(string: str) -> int:
    """ Return length of given string
    >>> strlen('')
    0
    >>> strlen('abc')
    3
    """
    if not isinstance(string, str):
        raise TypeError("Input must be a string")
    return len(string)

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    depths = []
    for group in groups:
        current_depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5)+1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [w for w in words if is_prime(len(w))]
    return " ".join(prime_length_words)

